how_to_use:
AnimationController _controller = AnimationController(
  duration: const Duration(seconds: 2),
  vsync: this,
);

AnimatedBuilder(
  animation: _controller,
  builder: (context, child) {
    return Transform.rotate(
      angle: _controller.value * 2 * 3.1416,
      child: child,
    );
  },
  child: Container(
    width: 100,
    height: 100,
    color: Colors.blue,
  ),
);
